def _get_fragment(self, chunk_iter, range_infos, storage_method):
    headers = dict()
    headers.update(self.headers)
    if range_infos:
        range_info = range_infos[0]
        headers['Range'] = 'bytes=%s-%s' % (range_info['req_fragment_start'], range_info['req_fragment_end'])
    reader = io.ChunkReader(chunk_iter, storage_method.ec_fragment_size, headers, self.connection_timeout, self.response_timeout, self.read_timeout, align=True)
    return (reader, reader.get_iter())

