async def get_difference(self):
    self.client._log[__name__].debug('Getting difference for entities')
    if self.update._channel_id:
        pts = self.update._pts_date
        try:
            where = await self.client.get_input_entity(self.update._channel_id)
        except ValueError:
            return
        result = await self.client(functions.updates.GetChannelDifferenceRequest(channel=where, filter=types.ChannelMessagesFilterEmpty(), pts=pts, limit=100, force=True))
    else:
        (pts, date) = self.update._pts_date
        result = await self.client(functions.updates.GetDifferenceRequest(pts=pts - 1, date=date, qts=0))
    if isinstance(result, (types.updates.Difference, types.updates.DifferenceSlice, types.updates.ChannelDifference, types.updates.ChannelDifferenceTooLong)):
        self.update._entities.update({utils.get_peer_id(x): x for x in itertools.chain(result.users, result.chats)})

